function dedupeIdBtrGeekPredictionRows<T extends {home_team_id:string;away_team_id:string;week_id?:string|null;scheduled_at:string;id:string;home_team:unknown;away_team:unknown}>(rows:T[], region:Region){
  if(region!=='ID')return rows;
  const codeOf=(team:unknown)=>{const item=Array.isArray(team)?team[0]:team;return (item as {code?:string}|null)?.code};
  const selected=new Map<string,T>();
  rows.forEach(row=>{
    const home=codeOf(row.home_team),away=codeOf(row.away_team);
    if([home,away].sort().join('|')!=='BTR|GEEK')return;
    const key=row.week_id||'week';
    const current=selected.get(key);
    if(!current){selected.set(key,row);return}
    const rowCanonical=home==='BTR'&&away==='GEEK';
    const currentCanonical=codeOf(current.home_team)==='BTR'&&codeOf(current.away_team)==='GEEK';
    if(rowCanonical!==currentCanonical)selected.set(key,rowCanonical?row:current);
    else if(new Date(row.scheduled_at).getTime()<new Date(current.scheduled_at).getTime())selected.set(key,row);
  });
  if(!selected.size)return rows;
  return rows.filter(row=>{
    const home=codeOf(row.home_team),away=codeOf(row.away_team);
    if([home,away].sort().join('|')!=='BTR|GEEK')return true;
    return selected.get(row.week_id||'week')?.id===row.id;
  });
}

